/* deriche.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "deriche.h"

#ifdef _OPENMP
/* OpenMP is used only via pragmas; the header is optional, but including
   it when _OPENMP is defined makes the intent explicit. */
#include <omp.h>
#endif


/* Array initialization. */
static
void init_array (int w, int h, DATA_TYPE* alpha,
		 DATA_TYPE POLYBENCH_2D(imgIn,W,H,w,h),
		 DATA_TYPE POLYBENCH_2D(imgOut,W,H,w,h))
{
  int i, j;

  *alpha=0.25; //parameter of the filter

  //input should be between 0 and 1 (grayscale image pixel)
  for (i = 0; i < w; i++)
     for (j = 0; j < h; j++)
	imgIn[i][j] = (DATA_TYPE) ((313*i+991*j)%65536) / 65535.0f;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int w, int h,
		 DATA_TYPE POLYBENCH_2D(imgOut,W,H,w,h))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("imgOut");
  for (i = 0; i < w; i++)
    for (j = 0; j < h; j++) {
      if ((i * h + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, imgOut[i][j]);
    }
  POLYBENCH_DUMP_END("imgOut");
  POLYBENCH_DUMP_FINISH;
}



/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Original code provided by Gael Deest */

/* The kernel has been optimized for:
   - Fewer passes over large arrays by fusing loops where possible.
   - Better cache locality (especially for y1/y2/imgOut).
   - Parallel execution across independent rows/columns using OpenMP.

   The mathematical operations and recursion order are preserved exactly;
   only the scheduling of independent work has been changed.
*/
static
void kernel_deriche[[gnu::flatten, gnu::noinline]](int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {

#pragma scop
    /* Precompute filter coefficients once. This removes redundant calls
       to EXP_FUN/POW_FUN and reduces scalar work inside the loops. */
    const DATA_TYPE one  = SCALAR_VAL(1.0);
    const DATA_TYPE two  = SCALAR_VAL(2.0);
    const DATA_TYPE zero = SCALAR_VAL(0.0);

    /* Exponential terms reused in the coefficients. */
    const DATA_TYPE exp_neg_alpha  = EXP_FUN(-alpha);        /* e^{-alpha}   */
    const DATA_TYPE exp_pos_2alpha = EXP_FUN(two * alpha);   /* e^{ 2*alpha} */
    const DATA_TYPE exp_neg_2alpha = EXP_FUN(-two * alpha);  /* e^{-2*alpha} */

    /* Normalization constant k (same formula as in the original code). */
    const DATA_TYPE k = (one - exp_neg_alpha) * (one - exp_neg_alpha) /
                        (one + two * alpha * exp_neg_alpha - exp_pos_2alpha);

    /* Filter coefficients (unchanged mathematically). */
    const DATA_TYPE a1 = k;
    const DATA_TYPE a2 = k * exp_neg_alpha * (alpha - one);
    const DATA_TYPE a3 = k * exp_neg_alpha * (alpha + one);
    const DATA_TYPE a4 = -k * exp_neg_2alpha;

    /* Vertical stage uses the same coefficients. */
    const DATA_TYPE a5 = a1;
    const DATA_TYPE a6 = a2;
    const DATA_TYPE a7 = a3;
    const DATA_TYPE a8 = a4;

    const DATA_TYPE b1 = POW_FUN(two, -alpha);
    const DATA_TYPE b2 = -exp_neg_2alpha;

    const DATA_TYPE c1 = one;
    const DATA_TYPE c2 = one;

    /* ------------------------------------------------------------------
     * 1) Horizontal pass
     *
     * For each row i:
     *   - run the causal (left-to-right) recursion to produce y1[i][*]
     *   - run the anti-causal (right-to-left) recursion to produce y2[i][*]
     *   - combine y1 and y2 immediately into imgOut[i][*]
     *
     * Each row is independent, so we parallelize over i.
     * ------------------------------------------------------------------ */
#pragma omp parallel for schedule(static)
    for (int i = 0; i < _PB_W; ++i) {
        /* Causal recursion state (left-to-right). */
        DATA_TYPE xm1 = zero;
        DATA_TYPE ym1 = zero;
        DATA_TYPE ym2 = zero;

        for (int j = 0; j < _PB_H; ++j) {
            const DATA_TYPE x = imgIn[i][j];
            const DATA_TYPE y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

            y1[i][j] = y;
            xm1 = x;
            ym2 = ym1;
            ym1 = y;
        }

        /* Anti-causal recursion state (right-to-left). */
        DATA_TYPE xp1 = zero;
        DATA_TYPE xp2 = zero;
        DATA_TYPE yp1 = zero;
        DATA_TYPE yp2 = zero;

        /* Run the anti-causal recursion and fuse the combination
           imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]) into this loop.
           This removes an extra full pass over the data. */
        for (int j = _PB_H - 1; j >= 0; --j) {
            const DATA_TYPE y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2[i][j] = y;

            const DATA_TYPE x = imgIn[i][j];
            xp2 = xp1;
            xp1 = x;
            yp2 = yp1;
            yp1 = y;

            imgOut[i][j] = c1 * (y1[i][j] + y);
        }
    }

    /* ------------------------------------------------------------------
     * 2) Vertical pass
     *
     * The horizontal result is now in imgOut. We apply the same pair of
     * causal/anti-causal recursions along columns to get the final 2D
     * Deriche filter output.
     *
     * For each column j:
     *   - run the causal (top-to-bottom) recursion, producing y1[*][j]
     *   - run the anti-causal (bottom-to-top) recursion, producing y2[*][j]
     *   - combine into imgOut[*][j] in-place
     *
     * Each column is independent, so we parallelize over j.
     * The in-place combination is safe because, in the anti-causal loop,
     * we always read imgOut[i][j] before writing the new value to it.
     * ------------------------------------------------------------------ */
#pragma omp parallel for schedule(static)
    for (int j = 0; j < _PB_H; ++j) {
        /* Causal recursion state (top-to-bottom). */
        DATA_TYPE tm1 = zero;
        DATA_TYPE ym1 = zero;
        DATA_TYPE ym2 = zero;

        for (int i = 0; i < _PB_W; ++i) {
            const DATA_TYPE x = imgOut[i][j];
            const DATA_TYPE y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

            y1[i][j] = y;
            tm1 = x;
            ym2 = ym1;
            ym1 = y;
        }

        /* Anti-causal recursion state (bottom-to-top). */
        DATA_TYPE tp1 = zero;
        DATA_TYPE tp2 = zero;
        DATA_TYPE yp1 = zero;
        DATA_TYPE yp2 = zero;

        /* Anti-causal recursion and final combination in-place. */
        for (int i = _PB_W - 1; i >= 0; --i) {
            const DATA_TYPE y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            y2[i][j] = y;

            const DATA_TYPE x = imgOut[i][j];  /* original horizontally filtered value */
            tp2 = tp1;
            tp1 = x;
            yp2 = yp1;
            yp1 = y;

            imgOut[i][j] = c2 * (y1[i][j] + y);
        }
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int w = W;
  int h = H;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(imgIn, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(imgOut, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y1, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y2, DATA_TYPE, W, H, w, h);


  /* Initialize array(s). */
  init_array (w, h, &alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_deriche (w, h, alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut), POLYBENCH_ARRAY(y1), POLYBENCH_ARRAY(y2));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(w, h, POLYBENCH_ARRAY(imgOut)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(imgIn);
  POLYBENCH_FREE_ARRAY(imgOut);
  POLYBENCH_FREE_ARRAY(y1);
  POLYBENCH_FREE_ARRAY(y2);

  return 0;
}
