  const DATA_TYPE e2a  = EXP_FUN(two * alpha);         /* e^{ 2 alpha} */
  const DATA_TYPE em2a = EXP_FUN(minus_two * alpha);   /* e^{-2 alpha} */

  const DATA_TYPE one_minus_em1 = one - em1;

  /* k = (1 - e^{-alpha})^2 / (1 + 2*alpha*e^{-alpha} - e^{2 alpha}) */
  const DATA_TYPE k = (one_minus_em1 * one_minus_em1) /
                      (one + two * alpha * em1 - e2a);

  const DATA_TYPE a1 = k;
  const DATA_TYPE a5 = k;

  const DATA_TYPE a2 = k * em1 * (alpha - one);
  const DATA_TYPE a6 = a2;

  const DATA_TYPE a3 = k * em1 * (alpha + one);
  const DATA_TYPE a7 = a3;

  const DATA_TYPE a4 = -k * em2a;
  const DATA_TYPE a8 = a4;

  const DATA_TYPE b1 = POW_FUN(two, -alpha);
  const DATA_TYPE b2 = -em2a;

  const DATA_TYPE c1 = one;
  const DATA_TYPE c2 = one;

  /* Use a single OpenMP parallel region to amortize thread creation
     overhead across all passes. Each #pragma omp for has an implicit
     barrier at the end, which preserves the original sequential
     ordering between passes. If the code is compiled without OpenMP
     support, these pragmas are ignored by the compiler, and behavior
     falls back to the original sequential execution. */
#pragma omp parallel
  {
    int i, j;

    /* Horizontal causal filter (left-to-right) on each row.
       Recurrence is along j; rows (i) are independent, so we
       parallelize across i. */
#pragma omp for schedule(static)
    for (i = 0; i < w_bound; i++)
    {
      DATA_TYPE ym1 = SCALAR_VAL(0.0);
      DATA_TYPE ym2 = SCALAR_VAL(0.0);
      DATA_TYPE xm1 = SCALAR_VAL(0.0);

      for (j = 0; j < h_bound; j++)
      {
        const DATA_TYPE x = imgIn_[i][j];
        const DATA_TYPE y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

        y1_[i][j] = y;

        xm1 = x;
        ym2 = ym1;
        ym1 = y;
      }
    }

    /* Horizontal anti-causal filter (right-to-left) on each row. */
#pragma omp for schedule(static)
    for (i = 0; i < w_bound; i++)
    {
      DATA_TYPE yp1 = SCALAR_VAL(0.0);
      DATA_TYPE yp2 = SCALAR_VAL(0.0);
      DATA_TYPE xp1 = SCALAR_VAL(0.0);
      DATA_TYPE xp2 = SCALAR_VAL(0.0);

      for (j = h_bound - 1; j >= 0; j--)
      {
        const DATA_TYPE y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

        y2_[i][j] = y;

        xp2 = xp1;
        xp1 = imgIn_[i][j];
        yp2 = yp1;
        yp1 = y;
      }
    }

    /* Combine horizontal passes: imgOut = c1 * (y1 + y2).
       No data dependencies; 2D parallelism is safe. */
#pragma omp for collapse(2) schedule(static)
    for (i = 0; i < w_bound; i++)
      for (j = 0; j < h_bound; j++)
        imgOut_[i][j] = c1 * (y1_[i][j] + y2_[i][j]);

    /* Vertical causal filter (top-to-bottom) on each column.
       Recurrence is along i; columns (j) are independent, so
       we parallelize across j. */
#pragma omp for schedule(static)
    for (j = 0; j < h_bound; j++)
    {
      DATA_TYPE tm1 = SCALAR_VAL(0.0);
      DATA_TYPE ym1 = SCALAR_VAL(0.0);
      DATA_TYPE ym2 = SCALAR_VAL(0.0);

      for (i = 0; i < w_bound; i++)
      {
        const DATA_TYPE x = imgOut_[i][j];
        const DATA_TYPE y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

        y1_[i][j] = y;

        tm1 = x;
        ym2 = ym1;
        ym1 = y;
      }
    }

    /* Vertical anti-causal filter (bottom-to-top) on each column. */
#pragma omp for schedule(static)
    for (j = 0; j < h_bound; j++)
    {
      DATA_TYPE tp1 = SCALAR_VAL(0.0);
      DATA_TYPE tp2 = SCALAR_VAL(0.0);
      DATA_TYPE yp1 = SCALAR_VAL(0.0);
      DATA_TYPE yp2 = SCALAR_VAL(0.0);

      for (i = w_bound - 1; i >= 0; i--)
      {
        const DATA_TYPE y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;

        y2_[i][j] = y;

        tp2 = tp1;
        tp1 = imgOut_[i][j];
        yp2 = yp1;
        yp1 = y;
      }
    }

    /* Final combination: imgOut = c2 * (y1 + y2).
       Again, fully parallel over both dimensions. */
#pragma omp for collapse(2) schedule(static)
    for (i = 0; i < w_bound; i++)
      for (j = 0; j < h_bound; j++)
        imgOut_[i][j] = c2 * (y1_[i][j] + y2_[i][j]);
  } /* end parallel region */

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int w = W;
  int h = H;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(imgIn, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(imgOut, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y1, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y2, DATA_TYPE, W, H, w, h);


  /* Initialize array(s). */
  init_array (w, h, &alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_deriche (w, h, alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut), POLYBENCH_ARRAY(y1), POLYBENCH_ARRAY(y2));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(w, h, POLYBENCH_ARRAY(imgOut)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(imgIn);
  POLYBENCH_FREE_ARRAY(imgOut);
