    const int W_ = _PB_W;
    const int H_ = _PB_H;

    /* Create restrict-qualified aliases to help the compiler optimize
       pointer arithmetic and avoid pessimistic aliasing assumptions. */
    DATA_TYPE (* restrict imgIn_ )[H_] = imgIn;
    DATA_TYPE (* restrict imgOut_)[H_] = imgOut;

    /* y1 and y2 are not needed as full 2D temporaries anymore.
       They are kept only to preserve the original interface. */
    (void)y1;
    (void)y2;

    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

#pragma scop
    /* Precompute exponentials and coefficients once. */
    const DATA_TYPE exp_neg_alpha   = EXP_FUN(-alpha);
    const DATA_TYPE exp_neg_2alpha  = EXP_FUN(-SCALAR_VAL(2.0) * alpha);
    const DATA_TYPE exp_pos_2alpha  = EXP_FUN( SCALAR_VAL(2.0) * alpha);

    const DATA_TYPE one_minus_exp   = SCALAR_VAL(1.0) - exp_neg_alpha;

    /* Same formula as in the original code, but reusing exp(-alpha). */
    const DATA_TYPE denom =
        SCALAR_VAL(1.0)
        + SCALAR_VAL(2.0) * alpha * exp_neg_alpha
        - exp_pos_2alpha;

    k  = (one_minus_exp * one_minus_exp) / denom;

    a1 = a5 = k;

    const DATA_TYPE k_mul_exp = k * exp_neg_alpha;

    a2 = a6 = k_mul_exp * (alpha - SCALAR_VAL(1.0));
    a3 = a7 = k_mul_exp * (alpha + SCALAR_VAL(1.0));
    a4 = a8 = -k * exp_neg_2alpha;

    b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
    b2 = -exp_neg_2alpha;

    c1 = c2 = SCALAR_VAL(1.0);

    /* Parallel region:
       - Each thread gets its own 1D buffers for the forward passes.
       - First loop: horizontal filtering per row.
       - Second loop: vertical filtering per column.
       Dependencies are only along each row/column, so rows/columns
       can be processed independently by different threads. */
#pragma omp parallel
    {
      /* Per-thread temporary buffers:
         - y1_line_h: forward horizontal response for one row (length H_).
         - y1_line_v: forward vertical   response for one column (length W_). */
      DATA_TYPE y1_line_h[H_];
      DATA_TYPE y1_line_v[W_];

      /* -------------------- Horizontal pass (per row) -------------------- */
#pragma omp for schedule(static)
      for (int i = 0; i < W_; ++i)
      {
        DATA_TYPE * restrict imgIn_row  = imgIn_[i];
        DATA_TYPE * restrict imgOut_row = imgOut_[i];

        /* Forward horizontal recurrence. */
        DATA_TYPE xm1 = SCALAR_VAL(0.0);
        DATA_TYPE ym1 = SCALAR_VAL(0.0);
        DATA_TYPE ym2 = SCALAR_VAL(0.0);

        for (int j = 0; j < H_; ++j)
        {
          const DATA_TYPE x = imgIn_row[j];
          const DATA_TYPE y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

          y1_line_h[j] = y;

          xm1 = x;
          ym2 = ym1;
          ym1 = y;
        }

        /* Backward horizontal recurrence and on-the-fly combination. */
        DATA_TYPE xp1 = SCALAR_VAL(0.0);
        DATA_TYPE xp2 = SCALAR_VAL(0.0);
        DATA_TYPE yp1 = SCALAR_VAL(0.0);
        DATA_TYPE yp2 = SCALAR_VAL(0.0);

        for (int j = H_ - 1; j >= 0; --j)
        {
          const DATA_TYPE y2_val = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
          const DATA_TYPE x      = imgIn_row[j]; /* Original input for the row. */

          /* Final horizontally filtered value for this pixel. */
          imgOut_row[j] = c1 * (y1_line_h[j] + y2_val);

          /* Update backward recurrence state. */
          xp2 = xp1;
          xp1 = x;
          yp2 = yp1;
          yp1 = y2_val;
        }
      } /* end horizontal pass */

      /* Implicit barrier here: all rows are finished before vertical pass. */

      /* -------------------- Vertical pass (per column) -------------------- */
#pragma omp for schedule(static)
      for (int j = 0; j < H_; ++j)
      {
        /* Forward vertical recurrence along column j. */
        DATA_TYPE tm1 = SCALAR_VAL(0.0);
        DATA_TYPE ym1 = SCALAR_VAL(0.0);
        DATA_TYPE ym2 = SCALAR_VAL(0.0);

        for (int i = 0; i < W_; ++i)
        {
          const DATA_TYPE x = imgOut_[i][j]; /* Horizontally filtered input. */
          const DATA_TYPE y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

          y1_line_v[i] = y;

          tm1 = x;
          ym2 = ym1;
          ym1 = y;
