 *  - Precomputes all scalar coefficients once.
 *  - Uses restrict-qualified 1D views for better alias analysis.
 *  - Improves memory-access patterns with explicit row/column strides.
 *  - Adds OpenMP parallelism on outer loops (if compiled with OpenMP).
 */
static
void kernel_deriche[[gnu::flatten, gnu::noinline]](int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {
