    const int w_eff = _PB_W;
    const int h_eff = _PB_H;

    /* Row-major layout: img[i][j] is stored at base + i*stride + j. */
    const int stride = h;

    /* 1D, restrict-qualified views into the 2D arrays.
       This helps the compiler assume no aliasing between arrays. */
    DATA_TYPE *restrict imgIn_  = &imgIn[0][0];
    DATA_TYPE *restrict imgOut_ = &imgOut[0][0];
    DATA_TYPE *restrict y1_     = &y1[0][0];
    DATA_TYPE *restrict y2_     = &y2[0][0];

    /* Filter coefficients. */
    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

