    /* Pre-compute all scalar coefficients once, exactly as in the original
       formula, but reusing the exponential evaluations. */
    const DATA_TYPE one  = SCALAR_VAL(1.0);
    const DATA_TYPE two  = SCALAR_VAL(2.0);
    const DATA_TYPE zero = SCALAR_VAL(0.0);

    const DATA_TYPE exp_neg_alpha  = EXP_FUN(-alpha);
    const DATA_TYPE exp_pos_2alpha = EXP_FUN(two * alpha);
    const DATA_TYPE exp_neg_2alpha = EXP_FUN(-two * alpha);

