            const DATA_TYPE x  = in_row[j];
            const DATA_TYPE yv = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

            y1_row[j] = yv;
            xm1       = x;
            ym2       = ym1;
            ym1       = yv;
        }
    }

