    #pragma omp parallel for schedule(static) if (w_eff * h_eff > 65536)
    for (int i = 0; i < w_eff; ++i) {
        DATA_TYPE yp1 = zero;
        DATA_TYPE yp2 = zero;
        DATA_TYPE xp1 = zero;
        DATA_TYPE xp2 = zero;

        DATA_TYPE       *restrict y2_row = y2_    + (size_t)i * (size_t)stride;
        const DATA_TYPE *restrict in_row = imgIn_ + (size_t)i * (size_t)stride;

        for (int j = h_eff - 1; j >= 0; --j) {
            const DATA_TYPE yv = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

            y2_row[j] = yv;
            xp2       = xp1;
            xp1       = in_row[j];
            yp2       = yp1;
            yp1       = yv;
        }
    }

    /* Combine horizontal passes: purely element-wise, fully parallel. */
    #pragma omp parallel for collapse(2) schedule(static) if (w_eff * h_eff > 65536)
    for (int i = 0; i < w_eff; ++i) {
        for (int j = 0; j < h_eff; ++j) {
            const size_t idx = (size_t)i * (size_t)stride + (size_t)j;
            imgOut_[idx] = c1 * (y1_[idx] + y2_[idx]);
        }
    }

    /* Vertical pass: forward recursion (top-to-bottom).
       Each column is independent and can be processed in parallel. */
    #pragma omp parallel for schedule(static) if (w_eff * h_eff > 65536)
    for (int j = 0; j < h_eff; ++j) {
        DATA_TYPE tm1 = zero;
        DATA_TYPE ym1 = zero;
        DATA_TYPE ym2 = zero;

        DATA_TYPE       *restrict y1_col  = y1_    + (size_t)j;
        const DATA_TYPE *restrict out_col = imgOut_ + (size_t)j;

        for (int i = 0; i < w_eff; ++i) {
            const DATA_TYPE x  = *out_col;
            const DATA_TYPE yv = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

            *y1_col = yv;
            tm1     = x;
            ym2     = ym1;
            ym1     = yv;

