    #pragma omp parallel for schedule(static) if (w_eff * h_eff > 65536)
    for (int j = 0; j < h_eff; ++j) {
        DATA_TYPE tp1 = zero;
        DATA_TYPE tp2 = zero;
        DATA_TYPE yp1 = zero;
        DATA_TYPE yp2 = zero;

        /* Start from the last row in this column. */
        DATA_TYPE       *restrict y2_col  = y2_    + (size_t)j + (size_t)(w_eff - 1) * (size_t)stride;
        const DATA_TYPE *restrict out_col = imgOut_ + (size_t)j + (size_t)(w_eff - 1) * (size_t)stride;

        for (int i = w_eff - 1; i >= 0; --i) {
            const DATA_TYPE yv = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;

            *y2_col = yv;
            tp2     = tp1;
            tp1     = *out_col;
            yp2     = yp1;
            yp1     = yv;

            y2_col  -= stride;
            out_col -= stride;
        }
    }

    /* Final combination of vertical passes: element-wise and parallel. */
    #pragma omp parallel for collapse(2) schedule(static) if (w_eff * h_eff > 65536)
    for (int i = 0; i < w_eff; ++i) {
        for (int j = 0; j < h_eff; ++j) {
            const size_t idx = (size_t)i * (size_t)stride + (size_t)j;
            imgOut_[idx] = c2 * (y1_[idx] + y2_[idx]);
        }
    }

#pragma endscop
}


